def redundancy_number(A: int, L: int, r: int) -> int:
    import math
    return sum(math.comb(L, i) * (A - 1) ** i for i in range(min(r, L) + 1))

def greedy_code(A, L, d):
    from itertools import product
    code = []
    for v in product(range(A), repeat=L):
        vol = tuple(v)
        if all(sum(a != b for a, b in zip(vol, c)) >= d for c in code):
            code.append(vol)
    return code

def de_bruijn(A, n):
    seq = []
    a = [0] * (A * n)
    def db(t, p):
        if t > n:
            if n % p == 0: seq.extend(a[1:p+1])
        else:
            a[t] = a[t-p]; db(t+1, p)
            for j in range(a[t-p]+1, A): a[t] = j; db(t+1, t)
    db(1, 1)
    return seq
